#!/usr/bin/env node

import { readFile, mkdir, writeFile } from 'node:fs/promises';
import { createRequire } from 'node:module';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const require = createRequire(import.meta.url);
const docsDirectory = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '../docs');
const packageDirectory = (name) => path.dirname(require.resolve(`${name}/package.json`));

// Keep vendored browser assets reproducible and covered by the root lockfile.
// Source maps are omitted from the published site; upstream license text is kept.
async function readAsset(packageName, source) {
  const text = await readFile(path.join(packageDirectory(packageName), source), 'utf8');
  return text
    .replace(/\/\*# sourceMappingURL=.*?\*\/|\/\/# sourceMappingURL=.*/g, '')
    .replace(/^[\t ]+$/gm, '');
}

async function copyAsset(packageName, source, destination) {
  await writeFile(path.join(docsDirectory, destination), await readAsset(packageName, source));
}

async function bundlePrism(destination, sources) {
  const directory = packageDirectory('prismjs');
  const { version } = JSON.parse(await readFile(path.join(directory, 'package.json'), 'utf8'));
  const parts = await Promise.all(sources.map((source) => readFile(path.join(directory, source), 'utf8')));
  await writeFile(path.join(docsDirectory, destination), [
    `/* PrismJS ${version}. Generated by scripts/build-docs-assets.mjs. MIT license: ../vendor/prismjs-LICENSE.txt */`,
    ...parts
  ].join('\n').replace(/^[\t ]+$/gm, ''));
}

await mkdir(path.join(docsDirectory, 'vendor'), { recursive: true });
await copyAsset('bootstrap', 'dist/css/bootstrap.min.css', 'styles/bootstrap.min.css');
// Assemble Popper separately so its lockfile version controls the shipped code,
// rather than the embedded version in Bootstrap's prebuilt bundle.
const bootstrapScripts = await Promise.all([
  readAsset('@popperjs/core', 'dist/umd/popper.min.js'),
  readAsset('bootstrap', 'dist/js/bootstrap.min.js')
]);
await writeFile(path.join(docsDirectory, 'scripts/bootstrap.min.js'), bootstrapScripts.join('\n'));
await copyAsset('bootstrap', 'LICENSE', 'vendor/bootstrap-LICENSE.txt');
await copyAsset('@popperjs/core', 'LICENSE.md', 'vendor/popper-LICENSE.txt');
await copyAsset('markdown-it', 'dist/markdown-it.min.js', 'scripts/markdown-it.min.js');
await copyAsset('markdown-it', 'LICENSE', 'vendor/markdown-it-LICENSE.txt');
await copyAsset('prismjs', 'LICENSE', 'vendor/prismjs-LICENSE.txt');
await bundlePrism('scripts/prism.js', [
  ...['core', 'markup', 'css', 'clike', 'javascript', 'bash', 'json']
    .map((language) => `components/prism-${language}.min.js`),
  'plugins/line-highlight/prism-line-highlight.min.js',
  'plugins/line-numbers/prism-line-numbers.min.js'
]);
await bundlePrism('styles/prism.css', [
  'themes/prism.css',
  'plugins/line-highlight/prism-line-highlight.css',
  'plugins/line-numbers/prism-line-numbers.css'
]);
console.log('Updated shared Bootstrap, markdown-it, and Prism assets from installed dependencies.');
